const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

function make(values, opts = {}) {
  const log = { opens: 0, reads: 0, closes: 0 };
  const source = { open: async () => { log.opens++; return {
    read: async () => { log.reads++; if (opts.readFail && log.reads === opts.readFail) throw opts.readErr; return values.shift() ?? null; },
    close: async () => { log.closes++; if (opts.closeErr) throw opts.closeErr; },
  }; } };
  return { log, service: new EventService(source, opts.mapper) };
}

async function main() {
  // exhaustion, lazy open, no read-ahead
  { const { log, service } = make(['a', 'b']);
    const g = service.stream(); assert.equal(log.opens, 0);
    assert.deepEqual(await g.next(), { value: 'A', done: false }); assert.deepEqual([log.opens, log.reads], [1, 1]);
    assert.deepEqual(await g.next(), { value: 'B', done: false }); assert.equal(log.reads, 2);
    assert.deepEqual(await g.next(), { value: undefined, done: true }); assert.deepEqual([log.reads, log.closes], [3, 1]);
    await g.next(); assert.equal(log.closes, 1); }
  // unopened return
  { const { log, service } = make(['a']); await service.stream().return(); assert.deepEqual(log, { opens: 0, reads: 0, closes: 0 }); }
  // break
  { const { log, service } = make(['a', 'b']);
    for await (const _ of service.stream()) break;
    assert.deepEqual(log, { opens: 1, reads: 1, closes: 1 }); }
  // break with close failure propagates
  { const ce = new Error('close'); const { service } = make(['a'], { closeErr: ce });
    await assert.rejects(async () => { for await (const _ of service.stream()) break; }, ce); }
  // read failure, with and without close failure
  { const re = new Error('read'); const { log, service } = make(['a'], { readFail: 1, readErr: re });
    await assert.rejects(service.stream().next(), re); assert.equal(log.closes, 1); }
  { const re = new Error('read'), ce = new Error('close'); const { log, service } = make(['a'], { readFail: 1, readErr: re, closeErr: ce });
    await assert.rejects(service.stream().next(), re); assert.equal(log.closes, 1); }
  // mapper failure
  { const me = new Error('map'), ce = new Error('close');
    const { log, service } = make(['a'], { mapper: () => { throw me; }, closeErr: ce });
    await assert.rejects(service.stream().next(), me); assert.equal(log.closes, 1); }
  // injected throw
  { const te = new Error('inj'); const { log, service } = make(['a', 'b']);
    const g = service.stream(); await g.next();
    await assert.rejects(g.throw(te), te); assert.deepEqual([log.reads, log.closes], [1, 1]); }
  { const te = new Error('inj'), ce = new Error('close'); const { log, service } = make(['a', 'b'], { closeErr: ce });
    const g = service.stream(); await g.next();
    await assert.rejects(g.throw(te), te); assert.equal(log.closes, 1); }
  // close failure on normal exhaustion propagates
  { const ce = new Error('close'); const { log, service } = make(['a'], { closeErr: ce });
    const g = service.stream(); await g.next();
    await assert.rejects(g.next(), ce); assert.equal(log.closes, 1); }
}
module.exports = main();

