import { Source } from './source';
import { mapEvent } from './mapper';
export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}
  async *stream(): AsyncGenerator<string> {
    // Generator bodies do not run until the first next(), so nothing is opened
    // for an unstarted generator (and return() on it never reaches here).
    const lease = await this.source.open();
    let primary: { error: unknown } | undefined;
    try {
      for (;;) {
        const value = await lease.read();
        if (value === null) break;
        const mapped = this.mapper(value);
        yield mapped; // consumer throw() surfaces here and is caught below
      }
    } catch (error) {
      primary = { error };
      throw error;
    } finally {
      // Runs exactly once: exhaustion, consumer return(), or any failure.
      if (primary) {
        try { await lease.close(); } catch { /* keep the original error */ }
      } else {
        await lease.close();
      }
    }
  }
}
